import { RouterModule, Routes } from '@angular/router';
import { UserListComponent } from './user-list/user-list.component';

// Component pages


const routes: Routes = [
  {
    path: '',
    component: UserListComponent,
  },

  
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
